async function refreshMaintenanceData(){
 const api=window.salesiaMaintenanceApi;if(!api)return;
 maintenanceLoading=true;maintenanceError='';render();
 try{const data=await api.load();maintenanceCategories=(data.categories||[]).map(c=>({...c,is_active:Boolean(c.is_active)}));maintenanceCustomers=(data.customers||[]).map(c=>({...c,segment:String(c.segment||'minorista').replace(/^./,x=>x.toUpperCase()),status:String(c.status||'activo').replace(/^./,x=>x.toUpperCase())}));maintenanceProducts=(data.products||[]).map(p=>({...p,price:Number(p.price),cost:Number(p.cost),stock_quantity:Number(p.stock_quantity),minimum_stock:Number(p.minimum_stock),status:String(p.status||'activo').replace(/^./,x=>x.toUpperCase()),category_name:maintenanceCategories.find(c=>c.id===p.category_id)?.name||''}));maintenanceSellers=(data.sellers||[]).map(v=>({...v,monthly_goal:Number(v.monthly_goal),status:String(v.status||'activo').replace(/^./,x=>x.toUpperCase())}));}
 catch(error){maintenanceError=maintenanceErrorText(error);maintenanceCategories=[];maintenanceCustomers=[];console.error('No se pudo cargar Mantenimiento desde Supabase:',error);}
 finally{maintenanceLoading=false;render();}
}
function editCategory(id){
 if(!window.salesiaMaintenanceApi)return;
 if(maintenanceLoading||maintenanceError)return toast('Restablece la conexión con Supabase antes de modificar categorías.');
 if(!maintenanceCanWrite())return toast('Tu rol tiene acceso de solo lectura a las categorías.');
 const item=maintenanceCategories.find(c=>c.id===id)||{};
 const fields=field('Nombre de categoría','name',item.name||'','text','required maxlength="100"')+field('Descripción','description',item.description||'','text','maxlength="300"')+(id?selectField('Estado','status',['Activo','Inactivo'],item.is_active?'Activo':'Inactivo'):'');
 modal(`${id?'Editar':'Nueva'} categoría`,`<form id="category-form" data-id="${esc(id||'')}"><div class="form-grid">${fields}</div><p class="error-text" id="category-error" role="alert"></p>${formEnd(id?'Guardar cambios':'Crear categoría')}</form>`);
}
async function toggleCategory(id){const item=maintenanceCategories.find(c=>c.id===id);if(!item||!window.salesiaMaintenanceApi)return;if(!maintenanceCanWrite())return toast('Tu rol no puede modificar categorías.');try{await window.salesiaMaintenanceApi.saveCategory(id,{name:item.name,description:item.description||'',is_active:!item.is_active});await refreshMaintenanceData();toast(item.is_active?'Categoría desactivada':'Categoría activada');}catch(error){toast(maintenanceErrorText(error));}}

function paymentMethodKey(value){const map={Efectivo:'efectivo',Tarjeta:'tarjeta',Transferencia:'transferencia',Yape:'yape',Plin:'plin',Otro:'otro',efectivo:'efectivo',tarjeta:'tarjeta',transferencia:'transferencia',yape:'yape',plin:'plin',otro:'otro'};return map[String(value||'Transferencia')]||'transferencia';}
