const sum=a=>a.reduce((x,y)=>x+y,0);
function stats(values){if(!values.length)return {n:0,total:0,mean:0,median:0,min:0,max:0};const a=[...values].sort((x,y)=>x-y),m=Math.floor(a.length/2);return {n:a.length,total:sum(a),mean:sum(a)/a.length,median:a.length%2?a[m]:(a[m-1]+a[m])/2,min:a[0],max:a[a.length-1]};}
function bayes(prior,likelihood,falsePositive){const evidence=prior*likelihood+(1-prior)*falsePositive;if(![prior,likelihood,falsePositive].every(n=>Number.isFinite(n)&&n>=0&&n<=1)||evidence===0)throw Error('Usa probabilidades entre 0 y 100. La evidencia debe ser mayor que cero.');return {posterior:prior*likelihood/evidence,evidence};}
function salesInPeriod(){const source=salesRecords().filter(s=>s.status!=='Anulada');if(period==='all')return source;const cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-Number(period)+1);return source.filter(s=>new Date(s.date+'T12:00:00')>=cutoff);}
function pill(s){return `<span class="pill ${['Pagada','Activo','Completado','Confirmado','Normal'].includes(s)?'green':['Pendiente','Preparando','Stock bajo'].includes(s)?'amber':['Inactivo','Anulada','Cancelado','Agotado'].includes(s)?'red':''}">${esc(s)}</span>`;}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4200);}
function modal(title,html){document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').innerHTML=html;document.querySelector('#dialog').showModal();}
function closeModal(){document.querySelector('#dialog').close();}
const button=(label,action,primary=false,extra='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${esc(label)}</button>`;
function panel(title,subtitle,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${body}</section>`;}
function card(label,value,note,k='chart'){return `<article class="stat"><div class="stat-label">${label}<span class="stat-icon">${icon(k)}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></article>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td class="empty" colspan="${headers.length}"><strong>No hay resultados</strong>Prueba otra búsqueda o crea el primer registro.</td></tr>`}</tbody></table></div>`;}
function toolbar(placeholder='Buscar por nombre o código…',options=[]){return `<div class="toolbar"><input class="filter-input" id="table-search" type="search" aria-label="Buscar registros" placeholder="${placeholder}" value="${esc(query)}">${options.length?`<select id="table-filter" aria-label="Filtrar registros"><option value="">Todos los estados</option>${options.map(o=>`<option ${filter===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:''}</div>`;}
function matches(v,status){return (!query||String(v).toLowerCase().includes(query.toLowerCase()))&&(!filter||status===filter);}
function tablePanel(title,subtitle,headers,rows,opts=[]){return panel(title,subtitle,toolbar(undefined,opts)+table(headers,rows)+`<div class="table-foot"><span>${rows.length} registro${rows.length===1?'':'s'} visibles</span><span>Espacio de trabajo</span></div>`);}
function opts(arr,selected,key='id',label='name'){return arr.map(x=>`<option value="${esc(x[key])}" ${x[key]===selected?'selected':''}>${esc(x[label])}</option>`).join('');}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,values,selected){return `<label class="field">${label}<select name="${name}">${values.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
const formEnd=label=>`<div class="form-actions">${button('Cancelar','close')}<button class="btn primary" type="submit">${label||'Guardar cambios'}</button></div>`;
function periodSelect(){return `<select class="period" id="period" aria-label="Periodo de análisis"><option value="7" ${period==='7'?'selected':''}>Últimos 7 días</option><option value="30" ${period==='30'?'selected':''}>Últimos 30 días</option><option value="all" ${period==='all'?'selected':''}>Todo el historial</option></select>`;}
function isAdminRole(){return window.salesiaRole==='administrador';}
function canViewModule(key){const role=window.salesiaRole;if(!role||role==='administrador')return true;const allowed={gerente:['inicio','mantenimiento','ventas','pedidos','inventario','analytics','probabilidad','insights','reportes'],vendedor:['inicio','mantenimiento','ventas','pedidos','inventario','reportes'],analista:['inicio','analytics','probabilidad','insights','reportes'],almacen:['inicio','mantenimiento','pedidos','inventario','reportes'],pendiente:[]};return (allowed[role]||[]).includes(key);}
function navigate(){const parts=location.hash.slice(1).split('/');if(parts[0]==='gestion')parts[0]='mantenimiento';if(parts[0]==='ventas'&&parts[1]==='pedidos'){parts[0]='pedidos';parts[1]='seguimiento';}current=MODULES.some(m=>m[0]===parts[0])?parts[0]:'inicio';if(!canViewModule(current))current='inicio';const m=MODULES.find(m=>m[0]===current);sub=m[4].some(s=>s[0]===parts[1])?parts[1]:m[4][0][0];query='';filter='';document.body.classList.remove('menu-open');render();if(current==='inventario'&&window.salesiaInventoryApi)refreshInventoryData();if(window.salesiaOperationsApi&&['inicio','ventas','pedidos'].includes(current))refreshOperationsData();}
function render(){const m=MODULES.find(m=>m[0]===current);document.title=`${m[1]} | SalesIA Enterprise`;document.querySelector('#breadcrumb').textContent=m[1];document.querySelector('#nav').innerHTML=MODULES.filter(x=>canViewModule(x[0])).map(x=>`${x[3]?`<div class="nav-label">${x[3]}</div>`:''}<a class="nav-item ${current===x[0]?'active':''}" href="#${x[0]}/${x[4][0][0]}" ${current===x[0]?'aria-current="page"':''}>${icon(x[2])}<span>${x[1]}</span>${x[0]==='insights'?`<span class="nav-count">${findings().length}</span>`:''}</a>${current===x[0]&&x[4].length>1?`<div class="subnav">${x[4].map(s=>`<a class="${sub===s[0]?'active':''}" href="#${x[0]}/${s[0]}">${s[1]}</a>`).join('')}</div>`:''}`).join('');
 document.querySelector('.workspace>div').innerHTML=`${esc(window.salesiaCurrentUser?.organization||state.company.name)}<small>Espacio de trabajo protegido</small>`;
  const desc={inicio:'Una visión clara de tu operación, tus resultados y tus próximas decisiones.',mantenimiento:'Administra los datos maestros: clientes, productos, categorías y vendedores.',ventas:'Registra ventas, consulta operaciones y controla sus pagos.',clientes:'Conoce a tus clientes y construye relaciones comerciales duraderas.',productos:'Un catálogo organizado para una operación más eficiente.',pedidos:'Registra, prepara y da seguimiento a pedidos antes de convertirlos en ventas.',inventario:'Controla las existencias y anticipa tus necesidades de reposición.',equipo:'Tu equipo comercial, sus objetivos y sus resultados.',analytics:'Convierte las operaciones comerciales en evidencia estadística.',probabilidad:'Explora eventos, distribuciones y probabilidades comerciales.',insights:'Hallazgos explicables, calculados a partir de tus ventas.',reportes:'Información comercial y estadística, lista para compartir.',administracion:'Gestiona la empresa, el equipo y la trazabilidad del espacio de trabajo.'};
  const adds={mantenimiento:maintenanceCanWrite()?(sub==='clientes'?['Nuevo cliente','new-customer']:sub==='productos'?['Nuevo producto','new-product']:sub==='categorias'?['Nueva categoría','new-category']:sub==='vendedores'?['Nuevo vendedor','new-seller']:null):null,ventas:sub==='nueva'?null:['Nueva venta','new-sale'],pedidos:['Nuevo pedido','new-order'],administracion:sub==='usuarios'&&isAdminRole()?['Añadir nueva cuenta','new-user']:null};
  const headingAction=current==='inicio'?`<div class="actions">${periodSelect()}${button('+ Nueva venta','new-sale',true)}</div>`:current==='inventario'?(inventoryCanWrite()?button('+ Registrar movimiento','movement',true):''):current==='ventas'&&sub==='nueva'?'':adds[current]?button('+ '+adds[current][0],adds[current][1],true):current==='mantenimiento'?'':current==='administracion'&&sub==='usuarios'?null:['analytics','probabilidad'].includes(current)?periodSelect():button('Exportar datos','export');
 document.querySelector('#content').innerHTML=`<div class="page-heading"><div><div class="eyebrow">${current==='inicio'?'TU CENTRO DE CONTROL':'WORKSPACE / '+m[1].toUpperCase()}</div><h1>${current==='inicio'?'Resumen ejecutivo':m[1]}</h1><p class="description">${desc[current]}</p></div>${headingAction}</div>${m[4].length>1?`<div class="tabs" aria-label="Secciones de ${m[1]}">${m[4].map(s=>`<a class="tab ${s[0]===sub?'active':''}" ${s[0]===sub?'aria-current="page"':''} href="#${current}/${s[0]}">${s[1]}</a>`).join('')}</div>`:''}${!storageOK?'<div class="callout">El almacenamiento local no está disponible. Exporta un respaldo antes de cerrar.</div>':''}${content()}`;
}
function gestionContent(){const oldCurrent=current,oldSub=sub;const route={clientes:['clientes','directorio'],productos:['productos','catalogo'],categorias:['productos','categorias'],vendedores:['equipo','directorio']}[sub]||['clientes','directorio'];current=route[0];sub=route[1];let html=current==='clientes'?customersView():current==='productos'?productsView():teamView();current=oldCurrent;sub=oldSub;return html;}
function content(){switch(current){case'inicio':return dashboard();case'mantenimiento':return gestionContent();case'ventas':return salesView();case'pedidos':return ordersView();case'inventario':return inventoryView();case'analytics':return analyticsView();case'probabilidad':return probabilityView();case'insights':return insightsView();case'reportes':return reportsView();case'administracion':return adminView();}}
function revenueChart(sales){const grouped=Object.create(null);sales.forEach(s=>grouped[s.date]=(grouped[s.date]||0)+s.total);const entries=Object.entries(grouped).sort((a,b)=>a[0].localeCompare(b[0]));if(!entries.length)return '<div class="empty">Registra ventas para visualizar su evolución.</div>';const max=Math.max(...entries.map(e=>e[1]),1),w=560,h=145;const pts=entries.map((e,i)=>[48+(entries.length===1?.5:i/(entries.length-1))*w,175-e[1]/max*h]);return `<svg class="chart" viewBox="0 0 640 220" role="img" aria-label="Ventas diarias en soles del periodo seleccionado"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#328d83" stop-opacity=".19"/><stop offset="100%" stop-color="#328d83" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(v=>`<line x1="48" x2="610" y1="${175-v*h}" y2="${175-v*h}" stroke="#edf1f4" stroke-dasharray="3 4"/><text x="0" y="${179-v*h}">${num(max*v/1000)}k</text>`).join('')}<path d="M${pts[0][0]},175 L${pts.map(p=>p.join(',')).join(' L')} L${pts.at(-1)[0]},175 Z" fill="url(#chartFill)"/><path d="M${pts.map(p=>p.join(',')).join(' L')}" fill="none" stroke="#328d83" stroke-width="2.3"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="2.5" fill="#328d83"><title>${datefmt(entries[i][0])}: ${money(entries[i][1])}</title></circle>`).join('')}${entries.filter((_,i)=>i%Math.max(1,Math.ceil(entries.length/6))===0).map(e=>{const i=entries.indexOf(e);return `<text x="${pts[i][0]}" y="208" text-anchor="middle">${datefmt(e[0])}</text>`;}).join('')}</svg>`;}
function categoryData(){const grouped=Object.create(null);salesInPeriod().forEach(s=>s.items.forEach(i=>{const c=productRecords().find(p=>p.id===i.product)?.category||'Otros';grouped[c]=(grouped[c]||0)+i.qty*i.price;}));return Object.entries(grouped).sort((a,b)=>b[1]-a[1]);}
function categoryChart(){const data=categoryData(),total=sum(data.map(d=>d[1])),colors=['#247e76','#548aaf','#a6c5cd','#dbdfd3'];let a=0;const stops=data.map((d,i)=>{const b=a+d[1]/(total||1)*100,s=`${colors[i%colors.length]} ${a}% ${b}%`;a=b;return s;});return `<div class="donut-layout"><div class="donut" style="background:conic-gradient(${stops.join(',')||'#eef2f4 0% 100%'})"><div><strong>${productRecords().length}</strong>productos</div></div><div class="legend-list">${data.map((d,i)=>`<div class="legend-row"><i style="background:${colors[i%colors.length]}"></i>${esc(d[0])}<strong>${(d[1]/(total||1)*100).toFixed(1)}%</strong></div>`).join('')||'<span class="tiny muted">Sin ventas</span>'}</div></div>`;}
function findings(){const a=stats(salesInPeriod().map(s=>s.total)),low=productRecords().filter(p=>Number(p.stock??p.stock_quantity??0)<=Number(p.min??p.minimum_stock??0)),pending=salesRecords().filter(s=>s.status==='Pendiente');const out=[];if(low.length)out.push({title:`${low.length} productos requieren reposición`,text:`${low.map(p=>p.name).join(', ')} se encuentran en el mínimo definido o por debajo.`,link:'#inventario/stock',tag:'Inventario'});if(a.n)out.push({title:'Comprende el valor de tus ventas',text:`El ticket promedio es ${money(a.mean)} y la mediana ${money(a.median)}, sobre ${a.n} ventas del periodo.`,link:'#analytics/estadistica',tag:'Estadística'});if(pending.length)out.push({title:`${pending.length} ventas pendientes de pago`,text:`Un total de ${money(sum(pending.map(s=>s.total)))} está pendiente de cobro. Prioriza su seguimiento.`,link:'#ventas/pagos',tag:'Cobranza'});return out;}
function insightList(){return findings().map(f=>`<a class="insight" href="${f.link}"><span class="insight-icon">↗</span><div><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p></div></a>`).join('')||'<p class="muted">Sin hallazgos para este periodo.</p>';}
function saleRows(sales,actions=true){return [...sales].sort((a,b)=>b.date.localeCompare(a.date)||String(b.code||b.id).localeCompare(String(a.code||a.id))).map(s=>[`<strong>${esc(s.code||s.id)}</strong><small>${datefmt(s.date)}</small>`,esc(customer(s.customer)),esc(seller(s.seller)),`<strong>${money(s.total)}</strong>`,pill(s.status),...(actions?[button('Ver detalle','sale-detail',false,`data-id="${esc(s.id)}"`)]:[])]);}
function dashboard(){if(!window.salesiaOperationsApi)return panel('Resumen no disponible','El sistema no mostrará datos locales de demostración como operaciones reales.',`<div class="panel-body"><div class="callout">La conexión de operaciones con Supabase no está inicializada. Vuelve a iniciar sesión y verifica la configuración de la empresa.</div>${button('Reintentar conexión','refresh-operations',true)}</div>`);if(!operationsReady){if(operationsLoading)return panel('Resumen ejecutivo','Cargando los datos empresariales desde Supabase…','<div class="panel-body"><p class="empty">Consultando ventas, productos y clientes…</p></div>');return panel('No se pudo cargar el resumen','El panel no mostrará cifras locales de demostración como si fueran operaciones reales.',`<div class="panel-body"><div class="callout">${esc(operationsError||'La conexión con Supabase no está disponible.')}</div>${button('Reintentar conexión','refresh-operations',true)}</div>`);}const sales=salesInPeriod(),s=stats(sales.map(s=>s.total)),products=productRecords(),customers=customerRecords(),low=products.filter(p=>Number(p.stock??p.stock_quantity??0)<=Number(p.min??p.minimum_stock??0)).length;return `<div class="welcome"><span class="welcome-icon">${icon('spark')}</span><div><h3>Buenas decisiones comienzan con buenos datos.</h3><p>Revisa tu operación y descubre oportunidades en un solo lugar.</p></div><a href="#analytics/resumen">Explorar Analytics ↗</a></div><div class="stats">${card('Ventas registradas',money(s.total),`${s.n} operaciones en el periodo`,'money')}${card('Ticket promedio',money(s.mean),'Media aritmética por transacción','chart')}${card('Clientes activos',customers.filter(c=>c.status==='Activo').length,`${new Set(sales.map(s=>s.customer)).size} con compras en el periodo`,'users')}${card('Alertas de inventario',String(low).padStart(2,'0'),'<strong>Requieren atención</strong> Stock mínimo','box')}</div><div class="grid-main">${panel('Evolución de ventas','Ingresos comerciales registrados · PEN',`<div class="panel-body"><div class="chart-summary"><div>Total del periodo<strong>${money(s.total)}</strong></div><span class="pill green">${s.n} transacciones</span></div>${revenueChart(sales)}</div>`,`<span class="legend"><span><b></b>Ventas</span></span>`)}${panel('Ventas por categoría','Participación sobre el importe vendido',`<div class="panel-body">${categoryChart()}</div><div class="panel-foot"><span>${categoryData().length} categorías con ventas</span><a class="link" href="#mantenimiento/productos">Ver catálogo →</a></div>`)}</div><div class="grid-main">${panel('Últimas ventas','Actividad reciente de tu negocio',table(['Operación','Cliente','Vendedor','Total','Estado'],saleRows(sales.slice(-5),false)),`<a href="#ventas/historial" class="link">Ver todas →</a>`)}${panel('Insights comerciales','Reglas estadísticas · Evidencia de tus datos',`<div class="panel-body">${insightList()}</div>`,`<span class="pill green">${findings().length} hallazgos</span>`)}</div><div class="quick-links">${[['cart','Registrar venta','ventas/nueva'],['users','Gestionar clientes','mantenimiento/clientes'],['chart','Analizar resultados','analytics/estadistica'],['file','Generar reporte','reportes/ventas']].map(([i,l,h])=>`<a class="quick-link" href="#${h}"><span>${icon(i)}</span>${l}<b>↗</b></a>`).join('')}</div>`;}
function salesView(){
 if(!window.salesiaOperationsApi)return panel('Ventas no conectadas','No se utilizarán ventas de demostración como registros empresariales.',`<div class="panel-body"><div class="callout">La conexión de operaciones con Supabase no está inicializada. Vuelve a iniciar sesión y comprueba la configuración de la empresa.</div>${button('Reintentar conexión','refresh-operations',true)}</div>`);
 if(!operationsReady){if(operationsLoading)return panel('Ventas y pagos','Cargando operaciones desde Supabase…','<div class="panel-body"><p class="empty">Consultando ventas y pagos…</p></div>');return panel('No se pudieron cargar las ventas','No se mostrarán ventas ficticias como operaciones reales.',`<div class="panel-body"><div class="callout">${esc(operationsError||'La conexión con Supabase no está disponible.')}</div>${button('Reintentar conexión','refresh-operations',true)}</div>`);}
 const sales=salesRecords();
 if(sub==='nueva')return panel('Registrar una venta','La venta se registra en Supabase; el stock se descuenta en la misma transacción. Si eliges Pagada, se registra el cobro completo.',`<div class="panel-body">${saleForm()}</div>`);
 if(sub==='pagos'){const pending=sales.filter(s=>s.status==='Pendiente'),paid=sales.filter(s=>s.status==='Pagada'),paidAmount=sum(paid.map(s=>s.total)),due=sum(pending.map(s=>Math.max(0,s.total-sum((s.payments||[]).filter(p=>p.status==='Confirmado').map(p=>Number(p.amount))))));const paymentRows=operationsPayments.filter(p=>matches(`${p.sale_code} ${customer(p.customer)} ${p.method} ${p.reference||''}`,p.status)).map(p=>[esc(p.sale_code),esc(customer(p.customer)),datefmt((p.paid_at||p.created_at||'').slice(0,10)),money(p.amount),esc(p.method),esc(p.reference||'—'),pill(p.status)]);const pendingRows=pending.filter(s=>matches(`${s.code||s.id} ${customer(s.customer)}`,s.status)).map(s=>[esc(s.code||s.id),esc(customer(s.customer)),money(s.total),pill(s.status),button('Registrar cobro','collect',false,`data-id="${esc(s.id)}"`)]);return `<div class="stats">${card('Ventas pagadas',money(paidAmount),`${paid.length} operaciones pagadas`,'money')}${card('Por cobrar',money(due),`${pending.length} ventas pendientes`,'money')}${card('Cobros registrados',String(operationsPayments.length),'Movimientos de pago en Supabase','cart')}${card('Ventas totales',String(sales.length),'Historial real','file')}</div>`+panel('Ventas pendientes de cobro','El cobro registra el saldo pendiente completo; no se admiten pagos parciales en esta versión.',`<div class="panel-body">${table(['Venta','Cliente','Importe pendiente','Estado','Acción'],pendingRows)}</div>`)+panel('Historial de pagos','Movimientos guardados en la tabla payments de Supabase.',`<div class="panel-body">${toolbar('Buscar venta, cliente, método o referencia…',['Confirmado','Rechazado','Reembolsado','Pendiente'])}${table(['Venta','Cliente','Fecha','Importe','Método','Referencia','Estado'],paymentRows)}<div class="table-foot"><span>${paymentRows.length} cobros visibles</span><span>Base de datos Supabase</span></div></div>`);}
 return tablePanel('Historial de ventas','Consulta operaciones confirmadas, pendientes o anuladas.', ['Operación','Cliente','Vendedor','Total','Estado','Detalle'],sales.filter(s=>matches(`${s.code||s.id} ${customer(s.customer)} ${seller(s.seller)}`,s.status)).map(s=>saleRows([s])[0]),['Pagada','Pendiente','Anulada']);
}
function ordersView(){
 if(!window.salesiaOperationsApi)return panel('Pedidos no conectados','No se utilizarán pedidos de demostración como registros empresariales.',`<div class="panel-body"><div class="callout">La conexión de operaciones con Supabase no está inicializada. Vuelve a iniciar sesión y comprueba la configuración de la empresa.</div>${button('Reintentar conexión','refresh-operations',true)}</div>`);
 if(!operationsReady){if(operationsLoading)return panel('Seguimiento de pedidos','Cargando pedidos desde Supabase…','<div class="panel-body"><p class="empty">Consultando pedidos y productos…</p></div>');return panel('No se pudieron cargar los pedidos','No se mostrarán pedidos ficticios como si fueran reales.',`<div class="panel-body"><div class="callout">${esc(operationsError||'La conexión con Supabase no está disponible.')}</div>${button('Reintentar conexión','refresh-operations',true)}</div>`);}
 const orders=orderRecords();const rows=orders.filter(o=>matches(`${o.code||o.id} ${customer(o.customer)} ${(o.items||[]).map(i=>product(i.product)).join(' ')}`,o.status)).map(o=>{const summary=(o.items||[]).map(i=>`${product(i.product)} × ${i.qty}`).join(', ')||'Sin detalle';let actions='';if(['Pendiente','Confirmado','Preparando'].includes(o.status)){actions='<div class="row-actions">';if(o.status==='Pendiente')actions+=button('Confirmar','order-confirm',false,`data-id="${esc(o.id)}"`);if(o.status!=='Preparando')actions+=button('Preparar','order-prepare',false,`data-id="${esc(o.id)}"`);actions+=button('Convertir en venta','order-sell',true,`data-id="${esc(o.id)}"`)+button('Cancelar','order-cancel',false,`data-id="${esc(o.id)}"`)+'</div>';}else actions=o.status==='Completado'?'<span class="tiny muted">Venta registrada</span>':'<span class="tiny muted">Pedido cerrado</span>';return [`<strong>${esc(o.code||o.id)}</strong><small>${datefmt(o.date)}</small>`,esc(customer(o.customer)),esc(summary),money(o.total),pill(o.status),actions];});
 return panel('Seguimiento de pedidos','Registra la solicitud comercial, confirma y prepara sus líneas; solo al convertirlo en venta se valida y descuenta el stock.',`<div class="panel-body"><div class="toolbar"><span class="tiny muted">${orders.length} pedido(s) en Supabase</span></div>${toolbar('Buscar pedido, cliente o producto…',['Pendiente','Confirmado','Preparando','Completado','Cancelado'])}${table(['Pedido','Cliente','Productos','Total estimado','Estado','Acciones'],rows)}<div class="table-foot"><span>${rows.length} pedidos visibles</span><span>Base de datos Supabase</span></div></div>`);
}
function inventoryView(){
 if(inventoryLoading)return panel('Inventario','Consultando existencias y movimientos en Supabase…','<div class="panel-body"><p class="empty">Cargando datos reales de inventario…</p></div>');
 if(inventoryError)return panel('No se pudo cargar Inventario','No se mostrarán existencias ni movimientos de demostración como si fueran registros reales.',`<div class="panel-body"><div class="callout">${esc(inventoryError)}</div>${button('Reintentar conexión','refresh-inventory',true)}</div>`);
 const productName=id=>inventoryProducts.find(p=>p.id===id)?.name||'Producto no disponible';
 const isLow=p=>Number(p.stock_quantity)<=Number(p.minimum_stock);
 const visibleProducts=inventoryProducts.filter(p=>(sub!=='alertas'||isLow(p))&&matches(`${p.name} ${p.code} ${p.category_name||''}`,String(p.status||'').replace(/^./,x=>x.toUpperCase())));
 if(sub==='historial'){
  const rows=inventoryMovements.filter(m=>matches(`${productName(m.product_id)} ${m.reason} ${m.movement_type} ${m.id}`,({entrada:'Entrada',salida:'Salida',ajuste:'Ajuste de saldo'})[m.movement_type]||m.movement_type)).map(m=>{
   const label=({entrada:'Entrada',salida:'Salida',ajuste:'Ajuste de saldo'})[m.movement_type]||m.movement_type;
   const quantity=m.movement_type==='entrada'?`+${m.quantity}`:m.movement_type==='salida'?`−${m.quantity}`:`Saldo final: ${m.quantity}`;
   return [esc(new Date(m.created_at).toLocaleString('es-PE',{dateStyle:'short',timeStyle:'short'})),esc(productName(m.product_id)),pill(label),quantity,esc(m.reason),m.unit_cost===null?'—':money(m.unit_cost)];
  });
  return panel('Historial de movimientos','Últimos 500 movimientos guardados en Supabase. Los registros de auditoría operativa no se editan ni eliminan desde esta pantalla.',`<div class="panel-body">${toolbar('Buscar por producto, tipo o motivo…',['Entrada','Salida','Ajuste de saldo'])}${table(['Fecha','Producto','Tipo','Cantidad / saldo final','Motivo','Costo unitario'],rows)}<div class="table-foot"><span>${rows.length} movimientos visibles</span><span>Base de datos Supabase</span></div></div>`);
 }
 const productRows=visibleProducts.map(p=>[
  `<strong>${esc(p.name)}</strong><small>${esc(p.code)}${p.category_name?` · ${esc(p.category_name)}`:''}</small>`,
  `${Number(p.stock_quantity)} ${esc('unidades')}`,
  `${Number(p.minimum_stock)} unidades`,
  pill(Number(p.stock_quantity)===0?'Agotado':isLow(p)?'Stock bajo':'Normal'),
  money(Number(p.stock_quantity)*Number(p.cost)),
  inventoryCanWrite()?button('Registrar movimiento','movement',false,`data-id="${esc(p.id)}"`):'<span class="tiny muted">Solo lectura</span>'
 ]);
 const stockTable=table(['Producto','Stock actual','Stock mínimo','Estado','Valor a costo','Acción'],productRows);
 if(sub==='movimientos')return panel('Entradas y salidas','Registra reposiciones, consumos, devoluciones o ajustes con una razón verificable.',`<div class="panel-body"><div class="callout">Las entradas suman existencias; las salidas las descuentan y no permiten stock negativo. Un ajuste establece el saldo físico contado. Los cambios se aplican en una transacción de Supabase.</div>${inventoryCanWrite()?button('+ Registrar movimiento','movement',true):'<p class="tiny muted">Tu rol puede consultar movimientos, pero no registrarlos.</p>'}${toolbar('Buscar producto por nombre o código…',['Activo','Agotado','Inactivo'])}${stockTable}<div class="table-foot"><span>${visibleProducts.length} productos visibles</span><span>Existencias actualizadas desde Supabase</span></div></div>`);
 const units=sum(inventoryProducts.map(p=>Number(p.stock_quantity)));
 const low=inventoryProducts.filter(isLow).length;
 const inventoryValue=sum(inventoryProducts.map(p=>Number(p.stock_quantity)*Number(p.cost)));
 return `<div class="stats">${card('Unidades disponibles',num(units),'Saldo actual registrado','layers')}${card('Productos en inventario',inventoryProducts.length,'Referencias de la empresa','box')}${card('Bajo el mínimo',low,'Incluye productos agotados','target')}${card('Valor estimado a costo',money(inventoryValue),'Stock × costo unitario','money')}</div>`+panel(sub==='alertas'?'Productos que requieren atención':'Control de existencias','El stock mínimo se configura en Mantenimiento → Productos.',`<div class="panel-body"><div class="callout">Las existencias proceden de Supabase. No se permite editar el stock desde la ficha del producto; registra una entrada, salida o ajuste para conservar la trazabilidad.</div>${toolbar('Buscar producto, código o categoría…',['Activo','Agotado','Inactivo'])}${stockTable}<div class="table-foot"><span>${visibleProducts.length} productos visibles</span><span>Base de datos Supabase</span></div></div>`);
}
async function refreshInventoryData(){
 const api=window.salesiaInventoryApi;if(!api)return;
 inventoryLoading=true;inventoryError='';render();
 try{
  const data=await api.load();
  inventoryProducts=(data.products||[]).map(p=>({...p,price:Number(p.price),cost:Number(p.cost),stock_quantity:Number(p.stock_quantity),minimum_stock:Number(p.minimum_stock),status:String(p.status||'activo').replace(/^./,x=>x.toUpperCase())}));
  inventoryMovements=(data.movements||[]).map(m=>({...m,quantity:Number(m.quantity),unit_cost:m.unit_cost===null?null:Number(m.unit_cost)}));
  maintenanceProducts=inventoryProducts.map(p=>({...p,category_name:p.category_name||''}));
 }catch(error){inventoryProducts=[];inventoryMovements=[];inventoryError=maintenanceErrorText(error);console.error('No se pudo cargar Inventario desde Supabase:',error);}
 finally{inventoryLoading=false;render();}
}

async function refreshOperationsData(){
 const api=window.salesiaOperationsApi;if(!api){operationsReady=false;operationsLoading=false;operationsError='El servicio de operaciones de Supabase no está disponible.';render();return;}
 operationsLoading=true;operationsError='';render();
 try{const data=await api.load();
  operationsCustomers=(data.customers||[]).map(c=>({...c,segment:titleStatus(c.segment),status:titleStatus(c.status)}));
  const categoryName=id=>(data.categories||[]).find(c=>c.id===id)?.name||maintenanceCategories.find(c=>c.id===id)?.name||'';
  operationsProducts=(data.products||[]).map(p=>({...p,price:Number(p.price),cost:Number(p.cost),stock:Number(p.stock_quantity),min:Number(p.minimum_stock),category:categoryName(p.category_id),status:titleStatus(p.status)}));
  operationsSellers=(data.sellers||[]).map(v=>({...v,goal:Number(v.monthly_goal),status:titleStatus(v.status)}));
  const paymentRows=(data.payments||[]).map(p=>({...p,amount:Number(p.amount),method:paymentMethodLabel(p.method),status:titleStatus(p.status)}));
  operationsPayments=paymentRows.map(p=>{const sale=(data.sales||[]).find(s=>s.id===p.sale_id);return {...p,sale_code:sale?.code||p.sale_id,customer:sale?.customer_id||null};});
  operationsSales=(data.sales||[]).map(row=>{const items=(data.saleItems||[]).filter(i=>i.sale_id===row.id).map(i=>({product:i.product_id,qty:Number(i.quantity),price:Number(i.unit_price)}));const payments=paymentRows.filter(p=>p.sale_id===row.id);return {id:row.id,code:row.code,date:String(row.sold_at||row.created_at).slice(0,10),customer:row.customer_id,seller:row.seller_id,status:titleStatus(row.status),subtotal:Number(row.subtotal),total:Number(row.total),notes:row.notes||'',items, payments, method:payments[0]?.method||'—'};});
  operationsOrders=(data.orders||[]).map(row=>({id:row.id,code:row.code,date:String(row.order_date||row.created_at).slice(0,10),customer:row.customer_id,seller:row.seller_id,status:titleStatus(row.status),total:Number(row.total),notes:row.notes||'',items:(data.orderItems||[]).filter(i=>i.order_id===row.id).map(i=>({product:i.product_id,qty:Number(i.quantity),price:Number(i.unit_price)}))}));
  operationsReady=true;operationsError='';
 }catch(error){operationsReady=false;operationsError=maintenanceErrorText(error);operationsCustomers=[];operationsProducts=[];operationsSellers=[];operationsSales=[];operationsOrders=[];operationsPayments=[];console.error('No se pudieron cargar ventas, pedidos y pagos desde Supabase:',error);}
 finally{operationsLoading=false;render();}
}
function customersView(){if(window.salesiaMaintenanceApi)return maintenanceCustomersView();if(sub==='segmentos'){return `<div class="report-grid">${['Corporativo','Pyme','Minorista'].map(seg=>{const clients=state.customers.filter(c=>c.segment===seg),sales=state.sales.filter(s=>clients.some(c=>c.id===s.customer));return `<article class="report-card"><span class="report-icon">${icon('users')}</span><h3>${seg}</h3><div class="stat-value">${clients.length}</div><p>${sales.length} compras registradas<br>${money(sum(sales.map(s=>s.total)))} en ventas</p><a class="btn" href="#mantenimiento/clientes">Ver directorio</a></article>`;}).join('')}</div>`;}if(sub==='historial')return tablePanel('Historial por cliente','Ventas acumuladas y frecuencia de compra.',['Cliente','Segmento','Compras','Total comprado','Ticket promedio','Última compra'],state.customers.filter(c=>matches(c.name+c.id,c.segment)).map(c=>{const sales=state.sales.filter(s=>s.customer===c.id),s=stats(sales.map(s=>s.total));return [esc(c.name),pill(c.segment),s.n,money(s.total),money(s.mean),sales.length?datefmt(sales.map(s=>s.date).sort().at(-1)):'Sin compras'];}),['Corporativo','Pyme','Minorista']);return tablePanel('Directorio de clientes','Información comercial centralizada y lista para consultar.',['Cliente','Correo','Segmento','Estado','Acciones'],state.customers.filter(c=>matches(c.name+c.id+c.email,c.status)).map(c=>[`<strong>${esc(c.name)}</strong><small>${esc(c.code||c.id)}</small>`,esc(c.email),pill(c.segment),pill(c.status),button('Editar ficha','edit-customer',false,`data-id="${c.id}"`)]),['Activo','Inactivo']);}
function productsView(){if(sub==='categorias')return window.salesiaMaintenanceApi?maintenanceCategoriesView():panel('Categorías de productos','Organiza el catálogo comercial.',`<div class="toolbar">${button('+ Nueva categoría','new-category',true)}</div>`+table(['Categoría','Productos','Unidades en stock'],state.categories.map(c=>[esc(c),state.products.filter(p=>p.category===c).length,sum(state.products.filter(p=>p.category===c).map(p=>p.stock))])));if(window.salesiaMaintenanceApi)return maintenanceProductsView();return tablePanel(sub==='precios'?'Precios y disponibilidad':'Catálogo de productos','Precios finales en soles. Utiliza movimientos para modificar existencias.',['Producto','Categoría','Precio final','Stock','Estado','Acciones'],state.products.filter(p=>matches(p.name+p.id+p.category,p.status)).map(p=>[`<strong>${esc(p.name)}</strong><small>${p.id}</small>`,esc(p.category),`<strong>${money(p.price)}</strong>`,`${p.stock} unidades`,pill(p.status),button('Editar','edit-product',false,`data-id="${p.id}"`)]),['Activo','Inactivo']);}
function teamView(){if(window.salesiaMaintenanceApi&&sub!=='rendimiento')return maintenanceSellersView();if(sub==='rendimiento'){return panel('Rendimiento comercial','Resultados acumulados de demostración frente a una meta individual.',`<div class="panel-body">${state.sellers.map(s=>{const sales=state.sales.filter(v=>v.seller===s.id),total=sum(sales.map(s=>s.total));return `<div class="rank-item"><span class="avatar">${esc(s.name.slice(0,2).toUpperCase())}</span><div class="rank-name">${esc(s.name)}<small>${sales.length} ventas · Meta ${money(s.goal)}</small><div class="progress"><span style="width:${Math.min(100,total/s.goal*100)}%"></span></div></div><strong>${money(total)}<small>${(total/s.goal*100).toFixed(1)}% de la meta</small></strong></div>`;}).join('')}</div>`);}return tablePanel('Equipo comercial','Directorio de vendedores y metas de venta.',['Vendedor','Correo','Meta comercial','Estado','Acciones'],state.sellers.filter(s=>matches(s.name+s.email,s.status)).map(s=>[`<strong>${esc(s.name)}</strong><small>${s.id}</small>`,esc(s.email),money(s.goal),pill(s.status),button('Editar','edit-seller',false,`data-id="${s.id}"`)]),['Activo','Inactivo']);}
function analyticsView(){const values=salesInPeriod().map(s=>s.total),s=stats(values);if(sub==='resumen')return `<div class="stats">${card('Total vendido',money(s.total),`${s.n} observaciones`,'money')}${card('Media',money(s.mean),'Ticket promedio','chart')}${card('Mediana',money(s.median),'Valor central de las ventas','target')}${card('Venta máxima',money(s.max),'Mayor importe del periodo','cart')}</div><div class="grid-main">${panel('Distribución temporal','Ventas registradas en el periodo',`<div class="panel-body">${revenueChart(salesInPeriod())}</div>`)}${panel('Participación comercial','Por categoría de producto',`<div class="panel-body">${categoryChart()}</div>`)}</div>`+panel('Ventas por vendedor','Comparación sobre el mismo periodo.',`<div class="panel-body">${state.sellers.map(v=>{const total=sum(salesInPeriod().filter(s=>s.seller===v.id).map(s=>s.total));return `<div class="bar-row"><span>${esc(v.name)}</span><div class="progress"><span style="width:${total/Math.max(s.total,1)*100}%"></span></div><strong>${money(total)}</strong></div>`;}).join('')}</div>`);if(sub==='estadistica')return `<div class="two-col">${panel('Media y mediana','Calculadas sobre el importe final de cada venta del periodo.',`<div class="panel-body"><div class="stats" style="grid-template-columns:1fr 1fr">${card('Media',money(s.mean),`${s.n} ventas`)}${card('Mediana',money(s.median),'Valores ordenados')}</div><div class="formula">Media = suma de importes / número de ventas<br>Mediana = valor central de la serie ordenada</div><div class="callout">${s.n?`La media ${s.mean>s.median?'supera':s.mean<s.median?'está por debajo de':'coincide con'} la mediana. Una diferencia puede reflejar ventas con importes extremos; no demuestra una causa comercial.`:'No hay ventas suficientes para calcular estadísticas.'}</div>${button('Guardar este análisis','save-analysis',true)}</div>`)}${panel('Detalle de la muestra','Dataset derivado de las ventas, sin introducir datos manuales.',`<div class="panel-body">${table(['Indicador','Valor'],[['Observaciones',s.n],['Suma',money(s.total)],['Mínimo',money(s.min)],['Máximo',money(s.max)],['Diferencia media − mediana',money(s.mean-s.median)]])}<p class="tiny muted">Incluye ventas pagadas y pendientes. Los registros operativos aún no se han migrado a PostgreSQL.</p></div>`)}</div>`;if(sub==='variables')return panel('Diccionario de variables','Clasificación estadística aplicada a la operación comercial.',table(['Variable','Naturaleza','Tipo','Origen','Ejemplo'],[['Monto de venta','Cuantitativa','Continua (registrada a centavos)','Ventas','S/ 1,250.50'],['Unidades por venta','Cuantitativa','Discreta','Detalle de venta','3 unidades'],['Categoría de producto','Cualitativa','Nominal','Catálogo','Tecnología'],['Método de pago','Cualitativa','Nominal','Pagos','Transferencia'],['Estado de venta','Cualitativa','Nominal','Ventas','Pagada'],['Stock disponible','Cuantitativa','Discreta','Inventario','24 unidades'] ]));if(sub==='datasets')return panel('Dataset de operaciones','Vista derivada de las ventas del periodo seleccionado.',table(['Venta','Fecha','Cliente','Unidades','Importe','Estado'],salesInPeriod().map(s=>[s.id,datefmt(s.date),esc(customer(s.customer)),sum(s.items.map(i=>i.qty)),money(s.total),pill(s.status)])),button('Descargar CSV','export'));return tablePanel('Historial de análisis','Instantáneas guardadas de los cálculos estadísticos y de Bayes.',['Fecha','Tipo','Muestra / evento','Resultado'],state.analyses.filter(a=>matches(a.type+a.date)).map(a=>[esc(a.date),pill(a.type),esc(a.sample),esc(a.result)]));}
function probabilityView(){const sales=salesInPeriod();if(sub==='bayes')return `<div class="two-col">${panel('Teorema de Bayes','Escenario ilustrativo: un cliente corporativo compra tecnología.',`<div class="panel-body"><form id="bayes-form"><div class="form-grid">${field('P(A) · Cliente corporativo (%)','prior',30,'number','required min="0" max="100" step="any"')}${field('P(B|A) · Tecnología si corporativo (%)','likelihood',70,'number','required min="0" max="100" step="any"')}${field('P(B|¬A) · Tecnología si no corporativo (%)','falsePositive',20,'number','required min="0" max="100" step="any"')}</div><div class="callout">A: cliente corporativo. B: compra de tecnología. Los valores iniciales son supuestos editables, no predicciones del negocio.</div><button class="btn primary" type="submit">Calcular probabilidad posterior</button><p id="bayes-error" class="error-text" role="alert"></p></form></div>`)}${panel('Probabilidad posterior','P(A|B) · Corporativo, dado que compra tecnología.',`<div class="panel-body" id="bayes-result"><div class="result-number">${lastBayes?(lastBayes.posterior*100).toFixed(2)+'%':'—'}</div><div class="result-sub">${lastBayes?'Resultado del último cálculo':'Completa los valores y ejecuta el cálculo.'}</div><div class="formula">P(B) = P(B|A)P(A) + P(B|¬A)P(¬A)<br><br>P(A|B) = P(B|A)P(A) / P(B)</div>${lastBayes?button('Guardar análisis','save-bayes'):''}</div>`)}</div>`;if(sub==='aleatorias'){const grouped=Object.create(null);sales.forEach(s=>{const q=sum(s.items.map(i=>i.qty));grouped[q]=(grouped[q]||0)+1;});return panel('Variable aleatoria: unidades por venta','Distribución empírica discreta del periodo. No implica una distribución teórica.',table(['Valor de X','Frecuencia','P(X = x)','Porcentaje'],Object.entries(grouped).sort((a,b)=>a[0]-b[0]).map(([q,n])=>[q,n,(n/(sales.length||1)).toFixed(4),(n/(sales.length||1)*100).toFixed(2)+'%'])))+panel('Valor esperado empírico','Promedio observado de unidades por transacción.',`<div class="panel-body"><div class="result-number">${num(sales.length?sum(sales.map(s=>sum(s.items.map(i=>i.qty))))/sales.length:0)}</div><p class="result-sub">Unidades por venta · ${sales.length} observaciones</p></div>`);}const paid=sales.filter(s=>s.status==='Pagada').length;return `<div class="stats">${card('P(venta pagada)',sales.length?(paid/sales.length*100).toFixed(1)+'%':'—',`${paid} de ${sales.length} ventas`)}${card('P(venta pendiente)',sales.length?((sales.length-paid)/sales.length*100).toFixed(1)+'%':'—',`${sales.length-paid} casos observados`)}${card('Tamaño de muestra',sales.length,'Ventas del periodo','layers')}${card('Tipo de probabilidad','Empírica','Frecuencia relativa observada','target')}</div>`+panel('Probabilidad por categoría','Evento: una venta contiene al menos un producto de la categoría.',table(['Evento','Casos favorables','Total de ventas','Probabilidad'],state.categories.map(c=>{const n=sales.filter(s=>s.items.some(i=>state.products.find(p=>p.id===i.product)?.category===c)).length;return [esc(c),n,sales.length,sales.length?(n/sales.length*100).toFixed(2)+'%':'Sin datos'];})))+'<div class="callout">Una venta puede incluir varias categorías, por lo que estos eventos no son necesariamente excluyentes.</div>';}
function insightsView(){if(sub==='historial')return tablePanel('Historial de hallazgos','Observaciones conservadas en el momento de su generación.',['Fecha','Área','Hallazgo','Evidencia'],state.findings.filter(f=>matches(f.title+f.text)).map(f=>[esc(f.date),pill(f.tag),esc(f.title),esc(f.text)]));return `<div class="welcome"><span class="welcome-icon">${icon('spark')}</span><div><h3>Resultados que puedes explicar</h3><p>Reglas determinísticas sobre tus datos. Esta versión no utiliza IA generativa ni una API externa.</p></div></div><div class="report-grid">${findings().map(f=>`<article class="report-card"><span class="pill green">${esc(f.tag)}</span><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p><a href="${f.link}" class="btn">Revisar evidencia ↗</a></article>`).join('')}</div><div style="margin-top:20px">${button('Guardar hallazgos actuales','save-findings',true)}</div>`;}
