 const companyName=window.salesiaCurrentUser?.organization||'Empresa conectada';
 return `<div class="two-col">${panel('Empresa vinculada a Supabase','Organización asociada a tu sesión.',`<div class="panel-body"><div class="setting-row"><div><h3>Razón social</h3><p>${esc(companyName)}</p></div><span class="pill green">Conectada</span></div><div class="setting-row"><div><h3>Cuenta actual</h3><p>${esc(window.salesiaCurrentUser?.name||'Usuario')} · ${esc(window.salesiaCurrentUser?.email||'')}</p></div><span class="pill">${esc(window.salesiaCurrentUser?.role||'Usuario')}</span></div><div class="callout">Esta vista es de solo lectura en esta fase. La edición del RUC, dirección y parámetros comerciales desde la interfaz se conectará a las tablas de Supabase en la siguiente etapa.</div></div>`)}${panel('Herramientas de demostración local','Estas opciones solo afectan datos guardados en este navegador.',`<div class="panel-body"><div class="setting-row"><div><h3>Respaldo local</h3><p>Descarga registros ficticios y cambios de la demostración.</p></div>${button('Exportar JSON','backup')}</div><div class="setting-row"><div><h3>Restaurar respaldo local</h3><p>Reemplaza los datos de demostración del navegador.</p></div>${button('Importar JSON','restore')}</div><div class="setting-row"><div><h3>Restablecer demostración</h3><p>Vuelve al estado inicial ficticio.</p></div>${button('Restablecer','reset')}</div><div class="callout">El respaldo local no contiene ni reemplaza los registros de la base de datos Supabase.</div></div>`)}</div>`;
