function saleLine(productId='',qty=1){return `<div class="sale-line form-grid" style="grid-template-columns:minmax(120px,1fr) 90px 32px;margin-top:12px;align-items:end"><label class="field">Producto<select name="product" required>${opts(productRecords().filter(p=>p.status==='Activo'),productId)}</select></label><label class="field">Cantidad<input name="qty" type="number" value="${qty}" min="1" max="100000" step="1" required></label><button class="icon-button" type="button" data-action="remove-line" aria-label="Quitar producto">×</button></div>`;}
function saleForm(){if(!customerRecords().some(c=>c.status==='Activo')||!sellerRecords().some(s=>s.status==='Activo')||!productRecords().some(p=>p.status==='Activo'))return '<div class="callout">Para registrar ventas, crea al menos un cliente activo, un vendedor activo y un producto activo en Mantenimiento. Los productos necesitan existencias registradas en Inventario.</div>';return `<form id="sale-form"><div class="form-grid"><label class="field">Cliente<select name="customer" required>${opts(customerRecords().filter(c=>c.status==='Activo'))}</select></label><label class="field">Vendedor<select name="seller" required>${opts(sellerRecords().filter(s=>s.status==='Activo'))}</select></label>${selectField('Estado de pago','status',['Pendiente','Pagada'],'Pendiente')}${selectField('Método de pago','method',['Transferencia','Tarjeta','Efectivo','Yape','Plin','Otro'],'Transferencia')}${field('Notas','notes','','text','maxlength="500"')}</div><div id="sale-lines">${saleLine()}</div><div style="margin-top:12px">${button('+ Añadir producto','add-line',false,'type="button"')}</div><div class="total-box"><span>Total estimado<small style="display:block">PEN · El importe final se calcula en PostgreSQL</small></span><strong id="sale-total">${money(productRecords().find(p=>p.status==='Activo')?.price||0)}</strong></div><div class="callout">La venta descuenta stock al registrarse. Si se marca Pagada, se registra un pago por el total; si queda Pendiente, puede cobrarse desde la sección Pagos. No se emiten comprobantes fiscales.</div><p class="error-text" role="alert"></p><div class="form-actions"><button class="btn primary" type="submit">Confirmar y registrar venta</button></div></form>`;}
function orderForm(){if(!customerRecords().some(c=>c.status==='Activo')||!sellerRecords().some(s=>s.status==='Activo')||!productRecords().some(p=>p.status==='Activo'))return '<div class="callout">Para registrar un pedido, crea al menos un cliente, un vendedor y un producto activos en Mantenimiento.</div>';return `<form id="order-form"><div class="form-grid"><label class="field">Cliente<select name="customer" required>${opts(customerRecords().filter(c=>c.status==='Activo'))}</select></label><label class="field">Vendedor<select name="seller" required>${opts(sellerRecords().filter(s=>s.status==='Activo'))}</select></label>${field('Notas del pedido','notes','','text','maxlength="500"')}</div><div id="sale-lines">${saleLine()}</div><div style="margin-top:12px">${button('+ Añadir producto','add-line',false,'type="button"')}</div><div class="total-box"><span>Total estimado<small style="display:block">El precio definitivo se recalcula desde el catálogo al registrar el pedido</small></span><strong id="sale-total">${money(productRecords().find(p=>p.status==='Activo')?.price||0)}</strong></div><div class="callout">Un pedido no descuenta ni reserva stock. La disponibilidad se comprueba al convertirlo en venta.</div><p class="error-text" role="alert"></p>${formEnd('Crear pedido')}</form>`;}
function calculateSale(form){return [...form.querySelectorAll('.sale-line')].map(line=>{const id=line.querySelector('[name="product"]').value,qty=Number(line.querySelector('[name="qty"]').value),p=productRecords().find(p=>p.id===id);return {product:id,qty,price:Number(p?.price)||0};});}
function recordSale(data,items,orderId){if(!state.customers.some(c=>c.id===data.customer&&c.status==='Activo'))throw Error('Selecciona un cliente activo.');if(!state.sellers.some(s=>s.id===data.seller&&s.status==='Activo'))throw Error('Selecciona un vendedor activo.');if(!items.length)throw Error('Añade al menos un producto.');const grouped=Object.create(null);items.forEach(i=>{if(!Number.isSafeInteger(i.qty)||i.qty<=0)throw Error('La cantidad debe ser un entero positivo.');grouped[i.product]=(grouped[i.product]||0)+i.qty;});Object.entries(grouped).forEach(([id,qty])=>{const p=state.products.find(p=>p.id===id);if(!p||p.status!=='Activo')throw Error('Producto no disponible.');if(p.stock<qty)throw Error(`Stock insuficiente para ${p.name}: quedan ${p.stock} unidades.`);});if(!['Pagada','Pendiente'].includes(data.status)||!['Transferencia','Tarjeta','Efectivo'].includes(data.method))throw Error('Estado o método no válido.');const order=orderId?state.orders.find(o=>o.id===orderId):null;if(orderId&&(!order||order.status==='Completado'))throw Error('Este pedido ya fue procesado o no existe.');const normalized=Object.entries(grouped).map(([id,qty])=>({product:id,qty,price:state.products.find(p=>p.id===id).price}));const sale={id:uid('VTA').toUpperCase(),date:today(),customer:data.customer,seller:data.seller,status:data.status,method:data.method,items:normalized,total:Math.round(sum(normalized.map(i=>i.qty*i.price))*100)/100};normalized.forEach(i=>{state.products.find(p=>p.id===i.product).stock-=i.qty;state.movements.unshift({id:uid('MOV'),date:new Date().toLocaleString('es-PE'),product:i.product,qty:i.qty,type:'Salida',reason:sale.id});});state.sales.push(sale);if(order)order.status='Completado';log(`Venta registrada: ${sale.id} · ${money(sale.total)}`);return sale;}
function editEntity(type,id){const configs={customer:['customers','cliente'],product:['products','producto'],seller:['sellers','vendedor'],user:['users','usuario']},[collection,label]=configs[type],source=type==='customer'&&window.salesiaMaintenanceApi?maintenanceCustomers:type==='product'&&window.salesiaMaintenanceApi?maintenanceProducts:type==='seller'&&window.salesiaMaintenanceApi?maintenanceSellers:state[collection],item=source.find(i=>i.id===id)||{};if(['customer','product','seller'].includes(type)&&window.salesiaMaintenanceApi&&maintenanceError)return toast('No se puede editar mientras falle la conexión con Supabase.');if(['customer','product','seller'].includes(type)&&window.salesiaMaintenanceApi&&!maintenanceCanWrite())return toast('Tu rol tiene acceso de solo lectura a los clientes.');let fields=field('Nombre','name',item.name,'text','required minlength="2" maxlength="160"');if(type==='product'){const categoryOptions=window.salesiaMaintenanceApi?maintenanceCategories.filter(c=>c.is_active).map(c=>`<option value="${esc(c.id)}" ${item.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join(''):state.categories.map(c=>`<option ${item.category===c?'selected':''}>${esc(c)}</option>`).join('');fields+=`<label class="field full">Categoría<select name="category"><option value="">Sin categoría</option>${categoryOptions}</select></label>`+field('Precio final (S/)','price',item.price??0,'number','required min="0" max="100000000" step="0.01"')+field('Costo unitario (S/)','cost',item.cost??0,'number','required min="0" max="100000000" step="0.01"')+field('Unidad de medida','unit',item.unit||'unidad','text','required maxlength="30"')+field('Descripción','description',item.description||'','text','maxlength="300"')+field('Stock mínimo','min',item.minimum_stock??item.min??5,'number','required min="0" max="100000000" step="1"');}else fields+=field('Correo','email',item.email,'email',type==='customer'?'maxlength="150"':'required maxlength="150"');if(type==='customer')fields+=field('Teléfono','phone',item.phone||'','tel','maxlength="40"')+field('Dirección','address',item.address||'','text','maxlength="250"')+field('Notas comerciales','notes',item.notes||'','text','maxlength="500"')+selectField('Segmento','segment',['Corporativo','Pyme','Minorista'],item.segment||'Minorista');if(type==='seller')fields+=field('Teléfono','phone',item.phone||'','tel','maxlength="40"')+field('Meta comercial mensual (S/)','goal',item.monthly_goal??item.goal??35000,'number','required min="0" max="100000000" step="0.01"');if(type==='user')fields+=selectField('Rol propuesto','role',['Administrador','Gerente','Vendedor','Analista','Almacén'],item.role);fields+=selectField('Estado','status',type==='product'?['Activo','Inactivo','Agotado']:['Activo','Inactivo'],item.status||'Activo');modal(`${id?'Editar':'Nuevo'} ${label}`,`<form id="entity-form" data-type="${type}" data-id="${id||''}"><div class="form-grid">${fields}</div><p id="entity-error" class="error-text" role="alert"></p>${formEnd()}</form>`);}
function movementForm(id){
 if(!window.salesiaInventoryApi)return toast('La conexión de inventario no está lista. Recarga el módulo.');
 if(!inventoryCanWrite())return toast('Tu rol solo puede consultar el inventario.');
 if(inventoryLoading||inventoryError)return toast('Restablece la conexión con Supabase antes de registrar movimientos.');
 const options=inventoryProducts.filter(p=>p.status!=='Inactivo').map(p=>`<option value="${esc(p.id)}" ${p.id===id?'selected':''}>${esc(p.code)} · ${esc(p.name)} (stock: ${Number(p.stock_quantity)})</option>`).join('');
 if(!options)return toast('Registra primero un producto activo en Mantenimiento → Productos.');
  modal('Registrar movimiento de inventario',`<form id="movement-form"><div class="form-grid"><label class="field full">Producto<select name="product" required>${options}</select></label>${selectField('Tipo de movimiento','type',['Entrada','Salida','Ajuste de saldo'])}${field('Cantidad / saldo final','qty',1,'number','required min="0" max="100000000" step="1"')}<label class="field full">Costo unitario (S/, opcional)<input name="unit_cost" type="number" min="0" max="100000000" step="0.01" placeholder="Ej. 125.50"></label><label class="field full">Motivo<input name="reason" required minlength="3" maxlength="150" placeholder="Ej. Reposición de proveedor, merma o conteo físico"></label></div><div class="callout">Entrada: suma unidades. Salida: descuenta unidades y no admite stock insuficiente. Ajuste de saldo: la cantidad ingresada será el nuevo stock físico contado; permite establecerlo en cero.</div><p class="error-text" role="alert"></p>${formEnd('Registrar movimiento')}</form>`);
}
function saleDetail(id){
 const s=salesRecords().find(item=>item.id===id);if(!s)return;
 const payments=(s.payments||[]).map(p=>[datefmt(String(p.paid_at||p.created_at||'').slice(0,10)),money(p.amount),esc(p.method),esc(p.reference||'—'),pill(p.status)]);
 const actions=`<div class="form-actions">${s.status==='Pendiente'?button('Registrar cobro','collect',true,`data-id="${esc(s.id)}"`)+button('Anular venta','cancel-sale',false,`data-id="${esc(s.id)}"`):''}${button('Cerrar','close')}</div>`;
 modal('Detalle de venta',`<div class="callout"><strong>${esc(s.code||s.id)}</strong><br>${datefmt(s.date)} · ${esc(customer(s.customer))}<br>Responsable: ${esc(seller(s.seller))} · ${esc(s.method||'Sin pago registrado')} · ${pill(s.status)}${s.notes?`<br>${esc(s.notes)}`:''}</div>${table(['Producto','Cantidad','Precio unitario','Total'],(s.items||[]).map(i=>[esc(product(i.product)),i.qty,money(i.price),money(i.qty*i.price)]))}<div class="total-box"><span>Total registrado</span><strong>${money(s.total)}</strong></div>${panel('Pagos asociados','Movimientos de cobro vinculados a esta venta.',table(['Fecha','Importe','Método','Referencia','Estado'],payments))}${actions}`);
}
function convertOrderForm(id){const o=orderRecords().find(item=>item.id===id);if(!o||!['Pendiente','Confirmado','Preparando'].includes(o.status))return toast('El pedido ya está cerrado o no existe.');modal('Convertir pedido en venta',`<div class="callout"><strong>${esc(o.code||o.id)}</strong><br>${esc(customer(o.customer))}<br>${(o.items||[]).map(i=>`${esc(product(i.product))} × ${i.qty}`).join('<br>')}<br><strong>Total estimado: ${money(o.total)}</strong></div><form id="order-convert-form" data-id="${esc(o.id)}"><div class="form-grid">${selectField('Estado de pago','status',['Pendiente','Pagada'],'Pendiente')}${selectField('Método de pago','method',['Transferencia','Tarjeta','Efectivo','Yape','Plin','Otro'],'Transferencia')}</div><div class="callout">Al confirmar, PostgreSQL creará la venta, comprobará el stock, descontará las existencias y marcará el pedido como completado en una sola transacción. Si eliges Pagada también se guardará el cobro completo.</div><p class="error-text" role="alert"></p>${formEnd('Convertir en venta')}</form>`);}
function cancelOrderForm(id){const o=orderRecords().find(item=>item.id===id);if(!o)return;modal('Cancelar pedido',`<form id="order-cancel-form" data-id="${esc(o.id)}">${field('Motivo de cancelación','reason','','text','required minlength="3" maxlength="300"')}<p class="error-text" role="alert"></p>${formEnd('Cancelar pedido')}</form>`);}
function cancelSaleForm(id){const s=salesRecords().find(item=>item.id===id);if(!s||s.status!=='Pendiente')return toast('Solo se pueden anular ventas pendientes de pago.');modal('Anular venta pendiente',`<form id="sale-cancel-form" data-id="${esc(s.id)}">${field('Motivo de anulación','reason','','text','required minlength="3" maxlength="300"')}<p class="error-text" role="alert"></p>${formEnd('Anular venta')}</form>`);}
function download(filename,content,mime){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(v){let s=String(v??'');if(/^[=+@\-\\t\\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportReport(type){let headers,rows,name;switch(type){case'products':headers=['Código','Producto','Categoría','Precio','Stock','Mínimo','Estado'];rows=state.products.map(p=>[p.id,p.name,p.category,p.price,p.stock,p.min,p.status]);name='Productos';break;case'customers':headers=['Código','Nombre','Correo','Segmento'];rows=state.customers.map(c=>[c.id,c.name,c.email,c.segment]);name='Clientes';break;case'sellers':headers=['Código','Nombre','Correo','Meta','Estado'];rows=state.sellers.map(s=>[s.id,s.name,s.email,s.goal,s.status]);name='Vendedores';break;case'statistics':{const s=stats(salesInPeriod().map(s=>s.total));headers=['Observaciones','Suma','Media','Mediana','Mínimo','Máximo'];rows=[[s.n,s.total,s.mean,s.median,s.min,s.max]];name='Estadisticas';break;}case'analyses':headers=['Fecha','Tipo','Muestra','Resultado'];rows=state.analyses.map(a=>[a.date,a.type,a.sample,a.result]);name='Analisis';break;default:headers=['Venta','Fecha','Cliente','Vendedor','Unidades','Total','Estado','Método'];rows=(type==='dataset'?salesInPeriod():state.sales).map(s=>[s.id,s.date,customer(s.customer),seller(s.seller),sum(s.items.map(i=>i.qty)),s.total,s.status,s.method]);name=type==='dataset'?'Dataset':'Ventas';}
 const file=`SalesIA-${name}-${today()}.csv`;download(file,'\\ufeff'+[headers,...rows].map(r=>r.map(csvCell).join(';')).join('\\r\\n'),'text/csv;charset=utf-8');state.exports.unshift({date:new Date().toLocaleString('es-PE'),name,file});log('Exportación: '+file);toast('Reporte CSV descargado');if(current==='reportes'&&sub==='historial')render();}
function searchModal(){modal('Buscar en el espacio de trabajo','<input id="module-search" class="filter-input" style="width:100%" placeholder="Ventas, inventario, Bayes…" aria-label="Buscar un módulo"><div class="search-results" id="module-results"></div>');searchResults('');document.querySelector('#module-search').focus();}
function searchResults(q){document.querySelector('#module-results').innerHTML=MODULES.flatMap(m=>m[4].filter(s=>(m[1]+' '+s[1]).toLowerCase().includes(q.toLowerCase())).map(s=>`<a class="search-result" href="#${m[0]}/${s[0]}" data-action="close">${m[1]} <span class="muted">/ ${s[1]}</span></a>`)).join('')||'<p class="empty">No se encontraron módulos.</p>';}
const ACTIONS={
 'menu':()=>document.body.classList.toggle('menu-open'),'close':closeModal,'search':searchModal,'notifications':()=>modal('Alertas y seguimiento',insightList()),
 'new-sale':()=>{if(!window.salesiaOperationsApi)return toast('Ventas solo está disponible con Supabase conectado.');if(!operationsReady||operationsError)return toast('Espera a que se carguen las ventas desde Supabase.');modal('Nueva venta',saleForm());},'sale-detail':id=>saleDetail(id),'refresh-operations':()=>refreshOperationsData(),
 'add-line':(_,el)=>{el.closest('form').querySelector('#sale-lines').insertAdjacentHTML('beforeend',saleLine());updateTotal(el.closest('form'));},
 'remove-line':(_,el)=>{const f=el.closest('form');if(f.querySelectorAll('.sale-line').length===1)return toast('Debe quedar al menos un producto.');el.closest('.sale-line').remove();updateTotal(f);},
 'new-customer':()=>editEntity('customer'),'edit-customer':id=>editEntity('customer',id),'new-product':()=>editEntity('product'),'edit-product':id=>editEntity('product',id),'new-seller':()=>editEntity('seller'),'edit-seller':id=>editEntity('seller',id),'new-user':()=>{if(isAdminRole()&&window.salesiaOpenCreateUser)window.salesiaOpenCreateUser();else toast('Solo un administrador puede crear cuentas.');},'edit-user':()=>toast('Los perfiles se administran desde las herramientas seguras de Supabase.'),
 'new-category':()=>window.salesiaMaintenanceApi?editCategory():modal('Nueva categoría',`<form id="category-form">${field('Nombre de categoría','name','','text','required maxlength="50"')}<p class="error-text" id="category-error" role="alert"></p>${formEnd('Crear categoría')}</form>`),
 'edit-category':id=>editCategory(id),'toggle-category':id=>toggleCategory(id),'refresh-maintenance':()=>refreshMaintenanceData(),'refresh-inventory':()=>refreshInventoryData(),
 'movement':id=>movementForm(id),
 'new-order':()=>{if(!window.salesiaOperationsApi)return toast('Pedidos solo está disponible con Supabase conectado.');if(!operationsReady||operationsError)return toast('Espera a que se carguen los pedidos desde Supabase.');modal('Nuevo pedido',orderForm());},
 'order-confirm':async id=>{try{if(!window.salesiaOperationsApi)throw Error('No hay conexión con Supabase.');await window.salesiaOperationsApi.updateOrderStatus(id,'confirmado');await refreshOperationsData();toast('Pedido confirmado en Supabase.');}catch(error){toast(maintenanceErrorText(error));}},
 'order-prepare':async id=>{try{if(!window.salesiaOperationsApi)throw Error('No hay conexión con Supabase.');await window.salesiaOperationsApi.updateOrderStatus(id,'preparando');await refreshOperationsData();toast('Pedido actualizado: en preparación.');}catch(error){toast(maintenanceErrorText(error));}},
 'order-sell':id=>convertOrderForm(id),'order-cancel':id=>cancelOrderForm(id),
 'collect':id=>{if(!window.salesiaOperationsApi)return toast('Los cobros requieren conexión con Supabase.');const s=salesRecords().find(s=>s.id===id);if(s&&s.status==='Pendiente')modal('Registrar cobro',`<form id="collect-form" data-id="${esc(s.id)}"><div class="callout">${esc(s.code||s.id)} · ${money(s.total)} · ${esc(customer(s.customer))}<br>El cobro completará el saldo pendiente de esta venta.</div>${selectField('Método de pago','method',['Transferencia','Tarjeta','Efectivo','Yape','Plin','Otro'],s.method==='—'?'Transferencia':s.method)}${field('Referencia (opcional)','reference','','text','maxlength="120"')}<p class="error-text" role="alert"></p>${formEnd('Confirmar cobro completo')}</form>`);},
 'cancel-sale':id=>cancelSaleForm(id),
 'save-analysis':()=>{const s=stats(salesInPeriod().map(s=>s.total));if(!s.n)return toast('Registra ventas antes de guardar un análisis.');state.analyses.unshift({date:new Date().toLocaleString('es-PE'),type:'Media y mediana',sample:`${s.n} ventas · Periodo ${period}`,result:`Media: ${money(s.mean)} · Mediana: ${money(s.median)}`});log('Análisis estadístico guardado');toast('Análisis guardado en el historial');},
 'save-bayes':()=>{if(!lastBayes)return;state.analyses.unshift({date:new Date().toLocaleString('es-PE'),type:'Bayes',sample:`P(A)=${lastBayes.prior}, P(B|A)=${lastBayes.likelihood}, P(B|¬A)=${lastBayes.falsePositive}`,result:`P(A|B)=${(lastBayes.posterior*100).toFixed(2)}%`});log('Análisis de Bayes guardado');toast('Análisis de Bayes guardado');},
 'save-findings':()=>{state.findings.unshift(...findings().map(f=>({...f,date:new Date().toLocaleString('es-PE')})));log('Hallazgos guardados');toast('Hallazgos conservados en el historial');},
 'report':id=>exportReport(id),'export':()=>exportReport(current==='mantenimiento'&&sub==='productos'?'products':current==='mantenimiento'&&sub==='clientes'?'customers':current==='mantenimiento'&&sub==='vendedores'?'sellers':current==='inventario'?'products':current==='analytics'?'dataset':'sales'),
 'print':()=>window.print(),'backup':()=>{download(`SalesIA-respaldo-${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('Respaldo descargado');},
 'restore':()=>modal('Restaurar un respaldo',`<form id="restore-form"><div class="callout">Se reemplazarán todos los datos actuales de esta demo. Exporta un respaldo antes si deseas conservarlos.</div><label class="field">Archivo JSON de SalesIA<input name="file" type="file" accept=".json,application/json" required></label><p id="restore-error" class="error-text" role="alert"></p>${formEnd('Importar y reemplazar')}</form>`),
 'reset':()=>modal('Restablecer datos de ejemplo',`<p class="description">Se eliminarán los cambios locales y se restaurará la demostración inicial. Esta acción no afecta a ningún sistema externo.</p><div class="form-actions">${button('Cancelar','close')}${button('Sí, restablecer demo','confirm-reset',true)}</div>`),
 'confirm-reset':()=>{state=seed();save();lastBayes=null;closeModal();render();toast('Datos de demostración restablecidos');},
 'help':()=>modal('Bienvenido a SalesIA',`<p class="description">Una interfaz empresarial de ventas y analítica, lista para explorar sin instalar dependencias.</p><div class="flow"><span>Cliente</span><span>Pedido</span><span>Venta</span><span>Pago y stock</span><span>Analytics</span></div><ol class="description"><li>Registra clientes y productos desde el menú lateral.</li><li>Crea una venta con uno o varios productos.</li><li>Consulta los movimientos y las alertas de stock.</li><li>Explora Analytics y guarda un análisis.</li><li>Exporta reportes o un respaldo desde Administración.</li></ol><div class="callout">El acceso, Mantenimiento e Inventario ya utilizan Supabase. Ventas, Pedidos, Analítica, Insights y Reportes siguen pendientes de migración; sus datos de demostración no deben considerarse operaciones empresariales reales.</div><p class="tiny muted">Atajo: pulsa / para buscar un módulo. Pulsa Esc para cerrar una ventana.</p>`)
};
function updateTotal(f){const t=f.querySelector('#sale-total');if(t)t.textContent=money(sum(calculateSale(f).map(i=>i.price*i.qty)));}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){if(el.tagName==='BUTTON')e.preventDefault();const fn=ACTIONS[el.dataset.action];if(fn)fn(el.dataset.id,el);}else if(document.body.classList.contains('menu-open')&&!e.target.closest('#sidebar'))document.body.classList.remove('menu-open');if(e.target.closest('#dialog a[href]'))closeModal();});
document.addEventListener('input',e=>{if(e.target.id==='table-search'){query=e.target.value;const p=e.target.selectionStart;render();const n=document.querySelector('#table-search');n.focus();n.setSelectionRange(p,p);}if(e.target.id==='module-search')searchResults(e.target.value);if(e.target.closest('#sale-form, #order-form'))updateTotal(e.target.closest('form'));});
document.addEventListener('change',e=>{if(e.target.id==='table-filter'){filter=e.target.value;render();}if(e.target.id==='period'){period=e.target.value;render();}if(e.target.closest('#sale-form, #order-form'))updateTotal(e.target.closest('form'));});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.querySelector('#dialog').open){e.preventDefault();searchModal();}if(e.key==='Escape')document.body.classList.remove('menu-open');});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.dataset?.submitting==='true')return;f.dataset.submitting='true';const submitButton=f.querySelector('[type="submit"]');if(submitButton)submitButton.disabled=true;const d=Object.fromEntries(new FormData(f));try{
 if(f.id==='sale-form'){
  if(window.salesiaOperationsApi){if(!operationsReady||operationsError)throw Error('No hay conexión activa con Supabase.');const lines=calculateSale(f);if(!d.customer||!d.seller||!lines.length||lines.some(i=>!i.product||!Number.isSafeInteger(i.qty)||i.qty<=0))throw Error('Selecciona cliente, vendedor y productos con cantidades positivas.');const status=d.status==='Pagada'?'pagada':'pendiente',method=paymentMethodKey(d.method);await window.salesiaOperationsApi.registerSale({customer_id:String(d.customer),seller_id:String(d.seller),items:lines.map(i=>({product_id:i.product,quantity:i.qty})),status,method,notes:String(d.notes||'')});closeModal();await refreshOperationsData();toast(status==='pagada'?'Venta y pago guardados en Supabase.':'Venta guardada en Supabase; queda pendiente de cobro.');}
  else throw Error('No se puede registrar una venta sin conexión con Supabase.');
 }
 if(f.id==='entity-form'){
  const type=f.dataset.type, id=f.dataset.id||null;
  d.name=String(d.name||'').trim();if(!d.name)throw Error('El nombre es obligatorio.');if(type==='customer'&&d.name.length<2)throw Error('El nombre del cliente debe tener al menos 2 caracteres.');
  if(type==='customer'&&window.salesiaMaintenanceApi){
   if(!maintenanceCanWrite())throw Error('Tu rol tiene acceso de solo lectura a los clientes.');
   const email=String(d.email||'').trim().toLowerCase();
   if(email&&maintenanceCustomers.some(x=>String(x.email||'').toLowerCase()===email&&x.id!==id))throw Error('Ya existe un cliente con ese correo en esta empresa.');
   await window.salesiaMaintenanceApi.saveCustomer(id,{name:d.name,email:String(d.email||''),phone:String(d.phone||''),address:String(d.address||''),segment:String(d.segment||'Minorista'),status:String(d.status||'Activo'),notes:String(d.notes||'')});
   closeModal();await refreshMaintenanceData();toast(id?'Cliente actualizado en Supabase':'Cliente creado en Supabase');
  }else if((type==='product'||type==='seller')&&window.salesiaMaintenanceApi){
   if(!maintenanceCanWrite())throw Error('Tu rol tiene acceso de solo lectura a Mantenimiento.');
   if(type==='product'){
    const price=Number(d.price),cost=Number(d.cost||0),minimum_stock=Number(d.min);
    if(!Number.isFinite(price)||price<0||!Number.isFinite(cost)||cost<0||!Number.isInteger(minimum_stock)||minimum_stock<0)throw Error('Revisa el precio, costo y stock mínimo.');
    await window.salesiaMaintenanceApi.saveProduct(id,{name:d.name,category_id:String(d.category||''),description:String(d.description||''),unit:String(d.unit||'unidad'),price,cost,minimum_stock,status:String(d.status||'Activo')});
   }else{
    const monthly_goal=Number(d.goal);if(!Number.isFinite(monthly_goal)||monthly_goal<0)throw Error('La meta comercial debe ser cero o mayor.');
    await window.salesiaMaintenanceApi.saveSeller(id,{name:d.name,email:String(d.email||''),phone:String(d.phone||''),monthly_goal,status:String(d.status||'Activo')});
   }
   closeModal();await refreshMaintenanceData();toast(id?'Registro actualizado en Supabase':'Registro creado en Supabase');
  }else{
   const collection={customer:'customers',product:'products',seller:'sellers',user:'users'}[type];
   if(d.email&&state[collection].some(x=>x.email.toLowerCase()===d.email.trim().toLowerCase()&&x.id!==id))throw Error('Ya existe un registro con este correo.');
   if(type==='product'){d.price=Number(d.price);d.min=Number(d.min);if(!(d.price>0)||!Number.isInteger(d.min)||d.min<0)throw Error('Revisa el precio y stock mínimo.');if('stock'in d){d.stock=Number(d.stock);if(!Number.isInteger(d.stock)||d.stock<0)throw Error('Stock inicial no válido.');}}
   if(type==='seller'){d.goal=Number(d.goal);if(!(d.goal>0))throw Error('La meta debe ser positiva.');}
   const old=state[collection].find(x=>x.id===id);if(old)Object.assign(old,d);else state[collection].push({id:uid({customer:'CLI',product:'PRD',seller:'EMP',user:'USR'}[type]).toUpperCase(),...d});log(`${old?'Actualización':'Creación'}: ${d.name}`);closeModal();render();toast('Registro guardado');
  }
 }
 if(f.id==='category-form'){
  d.name=String(d.name||'').trim();d.description=String(d.description||'').trim();if(!d.name)throw Error('Ingresa el nombre de la categoría.');
  if(window.salesiaMaintenanceApi){
   if(!maintenanceCanWrite())throw Error('Tu rol tiene acceso de solo lectura a las categorías.');
   const id=f.dataset.id||null;
   if(maintenanceCategories.some(c=>c.name.toLowerCase()===d.name.toLowerCase()&&c.id!==id))throw Error('Ya existe una categoría con ese nombre.');
   await window.salesiaMaintenanceApi.saveCategory(id,{name:d.name,description:d.description,is_active:id?d.status==='Activo':true});
   closeModal();await refreshMaintenanceData();toast(id?'Categoría actualizada en Supabase':'Categoría creada en Supabase');
  }else{
   if(state.categories.some(c=>c.toLowerCase()===d.name.toLowerCase()))throw Error('Ingresa una categoría nueva y no vacía.');state.categories.push(d.name);log('Categoría creada: '+d.name);closeModal();render();toast('Categoría creada');
  }
 }
 if(f.id==='movement-form'){
  const api=window.salesiaInventoryApi,product=inventoryProducts.find(p=>p.id===d.product),qty=Number(d.qty);
  const typeMap={'Entrada':'entrada','Salida':'salida','Ajuste de saldo':'ajuste'},movementType=typeMap[d.type];
  if(!api)throw Error('La conexión con Supabase no está disponible.');
  if(!inventoryCanWrite())throw Error('Tu rol no tiene permiso para registrar movimientos de inventario.');
  if(!product||!movementType||!Number.isSafeInteger(qty)||qty<0||(movementType!=='ajuste'&&qty===0))throw Error('Selecciona un producto y una cantidad válida. Las entradas y salidas requieren una cantidad mayor que cero.');
  const reason=String(d.reason||'').trim();if(reason.length<3)throw Error('El motivo debe tener al menos 3 caracteres.');
  const unitCost=String(d.unit_cost||'').trim()===''?null:Number(d.unit_cost);if(unitCost!==null&&(!Number.isFinite(unitCost)||unitCost<0))throw Error('El costo unitario debe ser cero o mayor.');
  await api.registerMovement({product_id:product.id,movement_type:movementType,quantity:qty,reason,unit_cost:unitCost});
  closeModal();await refreshInventoryData();toast('Movimiento registrado en Supabase. El stock se actualizó automáticamente.');
 }
 if(f.id==='order-form'){
  const lines=calculateSale(f);if(!d.customer||!d.seller||!lines.length||lines.some(i=>!i.product||!Number.isSafeInteger(i.qty)||i.qty<=0))throw Error('Completa cliente, vendedor y productos con cantidades positivas.');
  if(window.salesiaOperationsApi){if(!operationsReady||operationsError)throw Error('No hay conexión activa con Supabase.');await window.salesiaOperationsApi.registerOrder({customer_id:String(d.customer),seller_id:String(d.seller),items:lines.map(i=>({product_id:i.product,quantity:i.qty})),notes:String(d.notes||'')});closeModal();await refreshOperationsData();toast('Pedido guardado en Supabase; el stock todavía no se ha descontado.');}
  else throw Error('No se puede registrar un pedido sin conexión con Supabase.');
 }
 if(f.id==='order-convert-form'){if(!window.salesiaOperationsApi)throw Error('No hay conexión con Supabase.');const id=f.dataset.id,status=d.status==='Pagada'?'pagada':'pendiente';await window.salesiaOperationsApi.convertOrderToSale(id,status,paymentMethodKey(d.method));closeModal();await refreshOperationsData();toast(status==='pagada'?'Pedido convertido en venta pagada; stock actualizado.':'Pedido convertido en venta pendiente de cobro; stock actualizado.');}
 if(f.id==='order-cancel-form'){if(!window.salesiaOperationsApi)throw Error('No hay conexión con Supabase.');const reason=String(d.reason||'').trim();if(reason.length<3)throw Error('Indica el motivo de cancelación.');await window.salesiaOperationsApi.updateOrderStatus(f.dataset.id,'cancelado',reason);closeModal();await refreshOperationsData();toast('Pedido cancelado en Supabase.');}
 if(f.id==='sale-cancel-form'){if(!window.salesiaOperationsApi)throw Error('No hay conexión con Supabase.');const reason=String(d.reason||'').trim();if(reason.length<3)throw Error('Indica el motivo de anulación.');await window.salesiaOperationsApi.cancelSale(f.dataset.id,reason);closeModal();await refreshOperationsData();toast('Venta anulada y stock revertido por Supabase.');}

 if(f.id==='collect-form'){if(!window.salesiaOperationsApi||!operationsReady||operationsError)throw Error('No hay conexión activa con Supabase para registrar el cobro.');const sale=salesRecords().find(s=>s.id===f.dataset.id);if(!sale||sale.status!=='Pendiente')throw Error('La venta no está pendiente de pago.');await window.salesiaOperationsApi.registerPayment(f.dataset.id,paymentMethodKey(d.method),String(d.reference||''));closeModal();await refreshOperationsData();toast('Cobro registrado en Supabase.');}
 if(f.id==='company-form'){if(!d.name.trim())throw Error('Ingresa la razón social.');state.company={...d,name:d.name.trim()};log('Información de empresa actualizada');render();toast('Empresa actualizada');}
 if(f.id==='bayes-form'){const prior=Number(d.prior)/100,likelihood=Number(d.likelihood)/100,falsePositive=Number(d.falsePositive)/100;lastBayes={...bayes(prior,likelihood,falsePositive),prior,likelihood,falsePositive};document.querySelector('#bayes-error').textContent='';document.querySelector('#bayes-result').innerHTML=`<div class="result-number">${(lastBayes.posterior*100).toFixed(2)}%</div><div class="result-sub">Probabilidad posterior de A dado B</div><div class="formula">P(B) = ${(lastBayes.evidence*100).toFixed(2)}%<br>P(A|B) = (${likelihood} × ${prior}) / ${lastBayes.evidence.toFixed(4)}</div><div class="callout">Resultado condicionado a los supuestos ingresados. No es una predicción generada por IA.</div>${button('Guardar análisis','save-bayes')}`;}
 if(f.id==='restore-form'){const file=f.querySelector('input[type="file"]').files[0];if(!file||file.size>5000000)throw Error('Selecciona un respaldo JSON de hasta 5 MB.');const data=JSON.parse(await file.text());validateBackup(data);state=data;save();closeModal();render();toast('Respaldo restaurado');}
 }catch(err){const target=f.querySelector('.error-text');if(target)target.textContent=err.message;else toast(err.message);}finally{f.dataset.submitting='false';if(submitButton)submitButton.disabled=false;}});
function validateBackup(d){const fail=()=>{throw Error('Respaldo no compatible o con datos inválidos. Utiliza un JSON exportado por SalesIA v1.');};const text=v=>typeof v==='string'&&v.length<=3000;const positive=n=>Number.isFinite(n)&&n>=0;const integer=n=>Number.isSafeInteger(n)&&n>=0;
 if(!d||d.version!==1||!d.company||!['name','ruc','email','address'].every(k=>text(d.company[k])))fail();
 for(const k of ['categories','customers','products','sellers','sales','orders','movements','analyses','findings','exports','audit','users'])if(!Array.isArray(d[k])||d[k].length>30000)fail();
 if(!d.categories.length||!d.categories.every(text))fail();
 for(const k of ['customers','products','sellers','users'])if(!d[k].every(x=>x&&text(x.id)&&/^[A-Za-z0-9-]+$/.test(x.id)&&text(x.name)&&['Activo','Inactivo'].includes(x.status))||new Set(d[k].map(x=>x.id)).size!==d[k].length)fail();
 if(!d.products.every(p=>d.categories.includes(p.category)&&positive(p.price)&&p.price>0&&integer(p.stock)&&integer(p.min)))fail();
 if(!d.customers.every(c=>text(c.email)&&['Corporativo','Pyme','Minorista'].includes(c.segment))||!d.sellers.every(s=>text(s.email)&&positive(s.goal)&&s.goal>0)||!d.users.every(u=>text(u.email)&&text(u.role)))fail();
 if(!d.sales.every(s=>s&&text(s.id)&&/^[A-Za-z0-9-]+$/.test(s.id)&&/^\d{4}-\d{2}-\d{2}$/.test(s.date)&&Number.isFinite(Date.parse(s.date))&&d.customers.some(c=>c.id===s.customer)&&d.sellers.some(v=>v.id===s.seller)&&['Pagada','Pendiente'].includes(s.status)&&text(s.method)&&positive(s.total)&&Array.isArray(s.items)&&s.items.length>0&&s.items.every(i=>i&&d.products.some(p=>p.id===i.product)&&integer(i.qty)&&i.qty>0&&positive(i.price))&&Math.abs(sum(s.items.map(i=>i.qty*i.price))-s.total)<.011))fail();
 if(!d.orders.every(o=>o&&/^[A-Za-z0-9-]+$/.test(o.id)&&text(o.date)&&d.customers.some(c=>c.id===o.customer)&&d.products.some(p=>p.id===o.product)&&integer(o.qty)&&o.qty>0&&['Pendiente','Preparando','Completado'].includes(o.status)))fail();
 if(!d.movements.every(m=>m&&text(m.date)&&text(m.reason)&&d.products.some(p=>p.id===m.product)&&integer(m.qty)&&m.qty>0&&['Entrada','Salida'].includes(m.type)))fail();
 for(const [k,fields] of [['analyses',['date','type','sample','result']],['findings',['date','tag','title','text']],['exports',['date','name','file']],['audit',['date','user','action']]])if(!d[k].every(x=>x&&fields.every(f=>text(x[f]))))fail();
}
